# I suspect the top_id handling is wrong causing variable collisions with CardEnc.
# Let me fix that - CardEnc uses fresh vars starting after top_id, and I need to update counter.

from pysat.formula import CNF
from pysat.solvers import Solver
from pysat.card import CardEnc, EncType
from itertools import combinations

W, G, S = 5, 8, 3
N = G*S

counter = [1]
def newvar():
    v = counter[0]; counter[0]+=1; return v

x = [[[newvar() for g in range(G)] for p in range(N)] for w in range(W)]

cnf = CNF()

def add_exactly_one(lits):
    cnf.append(lits)
    for a,b in combinations(lits,2):
        cnf.append([-a,-b])

for w in range(W):
    for p in range(N):
        add_exactly_one(x[w][p])

for w in range(W):
    for g in range(G):
        lits = [x[w][p][g] for p in range(N)]
        enc = CardEnc.equals(lits=lits, bound=S, top_id=counter[0]-1, encoding=EncType.seqcounter)
        # update counter
        if enc.nv >= counter[0]:
            counter[0] = enc.nv + 1
        for cl in enc.clauses:
            cnf.append(cl)

for p1,p2 in combinations(range(N),2):
    t_lits = []
    for w in range(W):
        tw = newvar()
        t_lits.append(tw)
        for g in range(G):
            a = x[w][p1][g]; b = x[w][p2][g]
            cnf.append([-a,-b,tw])
    for a,b in combinations(t_lits,2):
        cnf.append([-a,-b])

print("vars:", counter[0], "clauses:", len(cnf.clauses))

# Symmetry breaking: week 0 groups assignment
# Golfers 0,1,2 in group 0; 3,4,5 in group 1; ... 21,22,23 in group 7
for p in range(N):
    g = p // S
    cnf.append([x[0][p][g]])

# Week fix for player 0: always in group 0
for w in range(W):
    cnf.append([x[w][0][0]])

s = Solver(name='cadical153', bootstrap_with=cnf.clauses)
print("solving...")
r = s.solve()
print("result:", r)
if r:
    m = set(s.get_model())
    result = []
    for w in range(W):
        for p in range(N):
            for g in range(G):
                if x[w][p][g] in m:
                    result.append(g); break
    pairs = set()
    ok = True
    for w in range(W):
        groups = [[] for _ in range(G)]
        for p in range(N):
            groups[result[w*N+p]].append(p)
        for gg in groups:
            if len(gg)!=3: ok=False
            for a,b in combinations(gg,2):
                if (a,b) in pairs: ok=False
                pairs.add((a,b))
    print("OK:", ok)
    print(result)
